import React, { useState, useRef, useEffect } from 'react';
import Tips from '../Tips/Tips';
import Employees from '../Employees/Employees';
import Summary from '../Summary/Summary';
import { GrAdd, GrUserManager, GrDocumentText } from 'react-icons/gr';
import './Tabs.css';

const tabs = [
  { title: 'Add Tips', icon: <GrAdd />, component: Tips },
  { title: 'Manage Employees', icon: <GrUserManager />, component: Employees },
  { title: 'View Summary', icon: <GrDocumentText />, component: Summary },
  {},
  {},
  {}
];

function Tabs() {
  return (
    <div className="popup">
      <div className="tabs">
        {tabs.map((tab, index) => (
          <React.Fragment key={index} className="tab">
            <input type="radio" id={`tab${index + 1}`} name="tab" defaultChecked={index === 0} />
            <label htmlFor={`tab${index + 1}`}>
              {tab.icon}
              <span>{tab.title}</span>
            </label>
          </React.Fragment>
        ))}
        <div className="marker">
          <div id="top"></div>
          <div id="bottom"></div>
        </div>
      </div>

      <div class="popup">
        <div class="tabs">
          <input type="radio" id="tab1" name="tab" checked="true" />
          <label for="tab1">FIRST TAB</label>
          <input type="radio" id="tab2" name="tab" />
          <label for="tab2">SECOND TAB</label>
          <input type="radio" id="tab3" name="tab" />
          <label for="tab3">THIRD TAB</label>
          <input type="radio" id="tab4" name="tab" />
          <label for="tab4">FOURTH TAB</label>
          <input type="radio" id="tab5" name="tab" />
          <label for="tab5">FIFTH TAB</label>
          <input type="radio" id="tab6" name="tab" />
          <label for="tab6">SIXTH TAB</label>
          <div class="marker">
            <div id="top"></div>
            <div id="bottom"></div>
          </div>
        </div>
      </div>



    </div>
  );
}

export default Tabs;
